const money=(v:number|null|undefined)=>`₹${Number(v||0).toLocaleString("en-IN",{maximumFractionDigits:0})}`;
function parseMessage(message:string|null){const out:Record<string,string>={};for(const line of String(message||"").split("\n")){const i=line.indexOf(":");if(i>0)out[line.slice(0,i).trim()]=line.slice(i+1).trim()}return out}
