  const [editing,setEditing]=useState(false),[activeResultType,setActiveResultType]=useState<"annual"|"common_test">("annual"),[showResultForm,setShowResultForm]=useState(false),[showAttendanceForm,setShowAttendanceForm]=useState(false),[showFeeForm,setShowFeeForm]=useState(false);
