    setEditData({full_name:a.student_name||"",date_of_birth:a.date_of_birth||"",previous_education:a.previous_education||p["Previous Education"]||"",father_name:a.father_name||p["Father's Name"]||"",mother_name:a.mother_name||p["Mother's Name"]||"",guardian_name:a.guardian_name||p["Guardian Name"]||"",guardian_relation:a.guardian_relation||p["Guardian Relationship"]||"",phone:a.mobile||p["Mobile Number 1"]||"",alternate_phone:a.contact_number_2||p["Mobile Number 2"]||"",occupation:a.occupation||p["Parent Occupation"]||"",address:a.full_address||a.address||p["Address"]||"",village:a.village_city||p["Village / Town"]||"",post_office:a.post_office||p["Post Office"]||"",district:a.district||p["District"]||"",state:a.state||p["State"]||"",pincode:a.pin_code||p["PIN Code"]||"",country:a.country||p["Country"]||"India",course:a.course||""});
