  const updateEdit=(k:keyof EditData,v:string)=>setEditData(x=>x?{...x,[k]:v}:x);

  const saveProfile=async()=>{if(!student||!editData)return;setSaving(true);setError("");try{const p=parseMessage(student.message);const msg=[`Application Number: ${p["Application Number"]||""}`,`Father's Name: ${editData.father_name||"Not provided"}`,`Mother's Name: ${editData.mother_name||"Not provided"}`,`Guardian Name: ${editData.guardian_name||"Not provided"}`,`Guardian Relationship: ${editData.guardian_relation||"Not provided"}`,`Mobile Number 1: ${editData.phone||"Not provided"}`,`Mobile Number 2: ${editData.alternate_phone||"Not provided"}`,`Parent Occupation: ${editData.occupation||"Not provided"}`,`Previous Education: ${editData.previous_education||"Not provided"}`,`Address: ${editData.address||"Not provided"}`,`Village / Town: ${editData.village||"Not provided"}`,`Post Office: ${editData.post_office||"Not provided"}`,`District: ${editData.district||"Not provided"}`,`State: ${editData.state||"Not provided"}`,`PIN Code: ${editData.pincode||"Not provided"}`,`Country: ${editData.country||"India"}`,`Identity Proof Type: ${student.student_document_type||p["Identity Proof Type"]||"Not provided"}`,`Student Photo: ${student.student_photo_url||p["Student Photo"]||""}`,`Identity Proof: ${student.student_document_url||p["Identity Proof"]||""}`].join("\n");const{error:e}=await supabase.from("admissions").update({student_name:editData.full_name,date_of_birth:editData.date_of_birth||null,previous_education:editData.previous_education||null,father_name:editData.father_name||null,mother_name:editData.mother_name||null,guardian_name:editData.guardian_name||null,guardian_relation:editData.guardian_relation||null,mobile:editData.phone||null,contact_number_2:editData.alternate_phone||null,occupation:editData.occupation||null,full_address:editData.address||null,address:editData.address||null,village_city:editData.village||null,post_office:editData.post_office||null,district:editData.district||null,state:editData.state||null,pin_code:editData.pincode||null,country:editData.country||null,course:editData.course||null,message:msg}).eq("id",student.id);if(e)throw e;setEditing(false);setNotice("Student profile updated successfully.");await loadAll()}catch(e:any){setError(e?.message||"Unable to update profile.")}finally{setSaving(false)}};
